const STAGES=[
 ['I','Motivate','Why does this problem need solving?','Explain the practical problem and why it matters.','The problem sets the questions for the literature.'],
 ['II','Connect the literature','What is known, and what is still missing?','Bring evidence of the gap together with foundations for a solution.','The gap motivates the capabilities required.'],
 ['III','Specify the response','What must a solution make possible?','State the necessary capabilities before choosing mechanisms.','These requirements constrain the method.'],
 ['IV','Explain the method','How does the method meet those needs?','Connect each method choice to the question it addresses.','The method defines what the evaluation must examine.'],
 ['V','Test the claims','What does the evidence actually support?','Compare the intended contribution with the evaluation and its scope.','The evidence sets limits on the conclusions.'],
 ['VI','Interpret & bound','What follows—and what remains open?','Explain the contribution, limitations and work still needed.','Return to the research problem within the demonstrated scope.'],
];

export function mountArgumentMap(root,p,currentId,esc){
 const nodes=p.blueprint.nodes,byId=id=>nodes.find(n=>n.id===id);
 const current=byId(currentId)||nodes.find(n=>n.id==='I-06');
 const order=section=>p.workbench.orders[section]||nodes.filter(n=>n.section===section).map(n=>n.id);
 const count=section=>order(section).filter(id=>p.selected[id]).length;
 root.innerHTML=`<section class="whole-argument"><div class="argument-map-heading"><div><p class="eyebrow">WISE / THE WHOLE ARGUMENT</p><h2>One paper. A connected line of reasoning.</h2><p>Start with the big picture. Open a section to see the moves inside it.</p></div><a class="map-resume" href="#paper/${esc(current.id)}"><span class="map-location-dot"></span><small>Your current move</small><strong>${esc(current.id)} · ${esc(current.title)}</strong><span>Return to my paragraph →</span></a></div><p class="tiny">This map follows your planning structure. Connections show the reader’s journey, not causal effects. It is a working plan, not supervisor approval.</p><ol class="argument-landscape" aria-label="Overall WISE argument flow">${STAGES.map(([section,verb,question,point,bridge],i)=>`<li class="argument-landmark ${section===current.section?'here':''}" style="--stage-hue:${225+i*12}"><button type="button" data-map-section="${section}" aria-controls="argument-map-detail" aria-expanded="${section===current.section}"><span class="map-stage-number">${String(i+1).padStart(2,'0')}</span><span class="map-stage-section">${section} · ${esc(p.blueprint.sections[section])}</span><strong>${verb}</strong><span class="map-stage-question">${question}</span><span class="map-stage-point">${point}</span><span class="map-stage-status">${section===current.section?'● You are working here · ':''}${count(section)}/${order(section).length} moves have selected text</span></button><div class="map-transition"><span aria-hidden="true">${i<STAGES.length-1?'→':'✓'}</span><span><strong>${i<STAGES.length-1?'Next: '+STAGES[i+1][0]:'Close the argument'}</strong> · ${bridge}</span></div></li>`).join('')}</ol><div class="argument-map-detail" id="argument-map-detail"></div><details class="argument-map-abstract"><summary>Abstract · write the summary after checking the argument</summary><p>The abstract brings the problem, response, evidence and contribution together. It is not a separate premise in the paper’s main argument.</p><a href="#paper/section-AB">Open abstract targets →</a></details></section>`;
 function show(section,scroll=false){
  const ids=order(section),stage=STAGES.find(s=>s[0]===section);
  root.querySelectorAll('[data-map-section]').forEach(b=>b.setAttribute('aria-expanded',String(b.dataset.mapSection===section)));
  const detail=root.querySelector('#argument-map-detail');
  const planned=JSON.stringify(ids),manuscript=JSON.stringify(p.workbench.manuscript_orders[section]||nodes.filter(n=>n.section===section).map(n=>n.id));
  detail.innerHTML=`<div class="section-row"><div><p class="eyebrow">ZOOM IN / ${section}</p><h3>${esc(p.blueprint.sections[section])}</h3><p>${stage[2]}</p></div><a class="btn secondary" href="#paper/section-${section}">Arrange these moves</a></div>${section==='II'?'<div class="map-literature-branches"><span><strong>A · Establish the gap</strong>What decision work remains unresolved?</span><span><strong>B · Build on foundations</strong>What can existing research contribute?</span><span><strong>Synthesis</strong>What still needs to be connected?</span></div>':''}<ol class="map-moves">${ids.map((id,i)=>{const n=byId(id),plan=p.workbench.plans[id]||{},selected=p.selected[id];return `<li class="${id===current.id?'map-move-current':''}"><span class="map-move-dot" aria-hidden="true">${i+1}</span><a href="#paper/${esc(id)}" ${id===current.id?'aria-current="step"':''}><small>${esc(id)} ${id===current.id?'· YOU ARE HERE':''}</small><strong>${esc(n.title)}</strong><span>${esc(plan.contribution||n.purpose)}</span><small>${plan.contribution?'Your saved intended point':'Overview-based purpose'} · ${selected?'✓ Text selected':'No text selected'}</small></a>${plan.handover?`<p class="map-move-handover">To the next move: ${esc(plan.handover)}</p>`:''}</li>`}).join('')}</ol><p class="tiny">${ids.length} proposed argument moves, not ${ids.length} compulsory paragraphs. Keep, adapt or combine wording only after checking its role.${planned!==manuscript?' This planning order differs from the manuscript order.':''}</p><a href="#paper/read-${section}">Read the text currently selected for this section →</a>`;
  if(scroll){detail.tabIndex=-1;detail.style.scrollMarginTop=((document.body.classList.contains('focus-mode')?document.querySelector('#focus-work')?.offsetHeight:0)||0)+24+'px';detail.focus({preventScroll:true});detail.scrollIntoView({block:'start',behavior:'smooth'});}
 }
 root.querySelectorAll('[data-map-section]').forEach(b=>b.onclick=()=>show(b.dataset.mapSection,true));
 show(current.section==='AB'?'I':current.section);
}
